const item = $input.first();
let data = item.json;

// Unwrap common AI Agent output envelopes without losing the raw response.
if (data && typeof data === 'object' && data.output !== undefined) data = data.output;

function extractJsonText(value) {
  let text = String(value ?? '').replace(/^\uFEFF/, '').trim();
  if (!text) throw new Error('AI returned an empty response.');

  // Remove a complete Markdown code fence, including ```json.
  const fenced = text.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
  if (fenced) text = fenced[1].trim();

  // If prose surrounds the JSON, isolate the first balanced JSON object.
  if (!text.startsWith('{')) {
    const start = text.indexOf('{');
    if (start < 0) throw new Error('No JSON object was found in the AI response.');
    let depth = 0, inString = false, escaped = false, end = -1;
    for (let i = start; i < text.length; i++) {
      const ch = text[i];
      if (inString) {
        if (escaped) escaped = false;
        else if (ch === '\\') escaped = true;
        else if (ch === '"') inString = false;
      } else {
        if (ch === '"') inString = true;
        else if (ch === '{') depth++;
        else if (ch === '}') {
          depth--;
          if (depth === 0) { end = i + 1; break; }
        }
      }
    }
    if (end < 0) throw new Error('The AI response contains an incomplete JSON object.');
    text = text.slice(start, end);
  }
  return text;
}

if (typeof data === 'string') {
  try {
    data = JSON.parse(extractJsonText(data));
  } catch (e) {
    return [{json:{
      valid:false,
      errors:['AI output could not be parsed as JSON: ' + String(e)],
      workflow:null,
      requirements:[],
      rawOutput:String(data).slice(0,12000)
    }}];
  }
}

// Some integrations wrap the parsed result one additional time.
if (data && typeof data === 'object' && data.output !== undefined) {
  let nested = data.output;
  if (typeof nested === 'string') {
    try { nested = JSON.parse(extractJsonText(nested)); }
    catch (e) {
      return [{json:{valid:false,errors:['Nested AI output could not be parsed: '+String(e)],workflow:null,requirements:[]}}];
    }
  }
  data = nested;
}

// Accept the structured wrapper; also diagnose a direct workflow object.
const workflow = data && data.workflow && typeof data.workflow === 'object' ? data.workflow : data;
const requirements = Array.isArray(data && data.requirements) ? data.requirements : [];
const errors = [];

if (!workflow || typeof workflow !== 'object' || Array.isArray(workflow)) {
  errors.push('Output must contain a workflow object.');
}
if (workflow && typeof workflow === 'object') {
  if (typeof workflow.name !== 'string' || !workflow.name.trim()) errors.push('Workflow name is missing.');
  if (!Array.isArray(workflow.nodes) || workflow.nodes.length < 2) errors.push('Workflow must contain at least two nodes.');
  if (!workflow.connections || typeof workflow.connections !== 'object' || Array.isArray(workflow.connections)) errors.push('connections must be an object.');
}

const nodes = workflow && Array.isArray(workflow.nodes) ? workflow.nodes : [];
const names = new Set();
const duplicateNames = new Set();

for (const [i, n] of nodes.entries()) {
  if (!n || typeof n !== 'object' || Array.isArray(n)) {
    errors.push(`Node at index ${i} is not an object.`);
    continue;
  }
  for (const key of ['name','type','typeVersion','position','parameters']) {
    if (n[key] === undefined || n[key] === null) errors.push(`Node ${i} is missing ${key}.`);
  }
  if (typeof n.name === 'string') {
    if (names.has(n.name)) duplicateNames.add(n.name);
    names.add(n.name);
  }
  if (typeof n.position !== 'undefined' &&
      (!Array.isArray(n.position) || n.position.length !== 2 || !n.position.every(Number.isFinite))) {
    errors.push(`Node "${n.name || i}" has an invalid position.`);
  }
  if (n.parameters !== undefined &&
      (!n.parameters || typeof n.parameters !== 'object' || Array.isArray(n.parameters))) {
    errors.push(`Node "${n.name || i}" parameters must be an object.`);
  }
}
for (const name of duplicateNames) errors.push(`Duplicate node name: "${name}".`);

const nodeNames = new Set(nodes.map(n => n && n.name).filter(v => typeof v === 'string'));
const connections = workflow && workflow.connections && typeof workflow.connections === 'object'
  ? workflow.connections : {};

for (const [source, outputs] of Object.entries(connections)) {
  if (!nodeNames.has(source)) errors.push(`Connection source "${source}" does not exist.`);
  if (!outputs || typeof outputs !== 'object' || Array.isArray(outputs)) {
    errors.push(`Connections for "${source}" must be an object.`);
    continue;
  }
  for (const [connectionType, branches] of Object.entries(outputs)) {
    if (!Array.isArray(branches)) {
      errors.push(`"${source}" connection "${connectionType}" must contain an array of branches.`);
      continue;
    }
    for (const [branchIndex, branch] of branches.entries()) {
      if (!Array.isArray(branch)) {
        errors.push(`"${source}" connection "${connectionType}" branch ${branchIndex} is invalid.`);
        continue;
      }
      for (const connection of branch) {
        if (!connection || typeof connection !== 'object') {
          errors.push(`Invalid connection from "${source}".`);
          continue;
        }
        if (!connection.node || !nodeNames.has(connection.node)) {
          errors.push(`Connection from "${source}" points to missing node "${connection.node || ''}".`);
        }
        if (connection.type !== connectionType) {
          errors.push(`Connection from "${source}" has type "${connection.type}" but is stored under "${connectionType}".`);
        }
        if (!Number.isInteger(connection.index) || connection.index < 0) {
          errors.push(`Connection from "${source}" to "${connection.node}" has an invalid index.`);
        }
      }
    }
  }
}

// Detect trigger nodes case-insensitively (e.g. chatTrigger).
const triggerNodes = nodes.filter(n => {
  if (!n || typeof n.type !== 'string') return false;
  const type = n.type.toLowerCase();
  return type.includes('trigger') ||
    type === 'n8n-nodes-base.webhook' ||
    type === 'n8n-nodes-base.manualtrigger' ||
    type === 'n8n-nodes-base.scheduletrigger';
});
if (nodes.length && triggerNodes.length === 0) errors.push('No recognizable trigger node was found.');

// n8n AI sub-node connections are stored FROM the sub-node TO the parent
// agent (for example, Gemini Model -> AI Agent). For reachability, the
// sub-node is a dependency OF the reachable parent, so add a reverse
// dependency edge for ai_* connections while preserving normal main edges.
const adjacency = new Map();
function addEdge(from, to) {
  if (!adjacency.has(from)) adjacency.set(from, []);
  adjacency.get(from).push(to);
}
for (const [source, outputs] of Object.entries(connections)) {
  if (!outputs || typeof outputs !== 'object' || Array.isArray(outputs)) continue;
  for (const [connectionType, branches] of Object.entries(outputs)) {
    if (!Array.isArray(branches)) continue;
    for (const branch of branches) {
      if (!Array.isArray(branch)) continue;
      for (const edge of branch) {
        if (!edge || typeof edge.node !== 'string' || !nodeNames.has(edge.node)) continue;
        if (connectionType === 'main') {
          addEdge(source, edge.node);
        } else if (connectionType.startsWith('ai_')) {
          // Invert AI dependency direction for traversal only.
          addEdge(edge.node, source);
        }
      }
    }
  }
}

const reachable = new Set();
const queue = triggerNodes.map(n => n.name);
while (queue.length) {
  const current = queue.shift();
  if (!current || reachable.has(current)) continue;
  reachable.add(current);
  for (const target of (adjacency.get(current) || [])) {
    if (!reachable.has(target)) queue.push(target);
  }
}
for (const n of nodes) {
  if (n && n.name && !reachable.has(n.name)) {
    errors.push(`Node "${n.name}" is not reachable from a trigger through execution flow or an attached AI dependency.`);
  }
}

// Enforce Gemini-only language models and require every AI Agent to have
// an incoming Gemini language-model connection.
for (const n of nodes) {
  if (n && typeof n.type === 'string' && n.type.includes('.lmChat') &&
      n.type !== '@n8n/n8n-nodes-langchain.lmChatGoogleGemini') {
    errors.push(`Non-Gemini language model "${n.name}" is not allowed. Use Google Gemini Chat Model.`);
  }
}
const agentNodes = nodes.filter(n => n && typeof n.type === 'string' &&
  n.type === '@n8n/n8n-nodes-langchain.agent');
for (const agent of agentNodes) {
  const attachedModels = [];
  for (const [source, outputs] of Object.entries(connections)) {
    const branches = outputs && outputs.ai_languageModel;
    if (!Array.isArray(branches)) continue;
    for (const branch of branches) {
      if (!Array.isArray(branch)) continue;
      if (branch.some(edge => edge && edge.node === agent.name)) {
        attachedModels.push(nodes.find(n => n && n.name === source));
      }
    }
  }
  if (attachedModels.length === 0) {
    errors.push(`AI Agent "${agent.name}" has no connected language model.`);
  } else if (attachedModels.some(m => !m || m.type !== '@n8n/n8n-nodes-langchain.lmChatGoogleGemini')) {
    errors.push(`AI Agent "${agent.name}" must use Google Gemini Chat Model only.`);
  }
}

// Requirement coverage is mandatory for the generated wrapper.
if (!Array.isArray(data && data.requirements) || requirements.length === 0) {
  errors.push('The AI did not return a non-empty requirements list.');
} else {
  for (const [i, req] of requirements.entries()) {
    if (!req || typeof req !== 'object' || !req.id || !req.description ||
        !Array.isArray(req.implementedBy) || req.implementedBy.length === 0) {
      errors.push(`Requirement ${i + 1} is missing id, description, or implementedBy.`);
      continue;
    }
    const mappedNodes = [];
    for (const nodeName of req.implementedBy) {
      const mapped = nodes.find(n => n && n.name === nodeName);
      if (!mapped) errors.push(`Requirement "${req.id}" references missing node "${nodeName}".`);
      else {
        mappedNodes.push(mapped);
        if (!reachable.has(nodeName)) errors.push(`Requirement "${req.id}" references node "${nodeName}" that is not connected to the trigger through execution flow or an attached AI dependency.`);
      }
    }
    if (Array.isArray(req.expectedNodeTypes) && req.expectedNodeTypes.length > 0 &&
        !mappedNodes.some(n => req.expectedNodeTypes.includes(n.type))) {
      errors.push(`Requirement "${req.id}" expects one of node types [${req.expectedNodeTypes.join(', ')}], but none of its implementedBy nodes has an allowed type.`);
    }
  }
}

return [{json:{
  valid:errors.length === 0,
  errors,
  workflow:workflow || null,
  requirements,
  implementationSummary:data && data.implementationSummary ? data.implementationSummary : ''
}}];
